const { _point } = require("./_point.js")

class IRISIterator {
  
  constructor (node, view) {
    this._iris = node._iris
    this._global_name = node._global_name
    this._subscripts = node._subscripts
    this._start = node._start._iteratorCopy()
    this._stop = node._stop._iteratorCopy()
    this._reversed = node._reversed
    this._view = view
    this._at_end = false
  }

  [Symbol.iterator] () {
    return this
  }

  get [Symbol.toStringTag] () {
    return 'Iterator'
  }

  next () {
    // if (this._at_end) {
    //   return { done: true }
    // }

    let keyValue
    if (this._start._inclusive) {
      const dollarData = this._iris.isDefined(this._global_name, ...this._subscripts, this._start._key)
      if (dollarData === 0) {
        keyValue = this._nextNode()
      } else if (dollarData === 10) {
        if (this._hasPassedStop(this._start._key)) {
          this._at_end = true
          return { done: true }
        }
        keyValue = [this._start._key, undefined]
      } else {
        if (this._hasPassedStop(this._start._key)) {
          this._at_end = true
          return { done: true }
        }
        keyValue = [this._start._key, this._iris.get(this._global_name, ...this._subscripts, this._start._key)]
      }
    } else {
      keyValue = this._nextNode()
      if (this._at_end) {
        return { done: true }
      }
    }

    // check if we are at end
    const returnedKey = keyValue[0]
    
    this._at_end = !returnedKey || (returnedKey.length === 0)
    if (this._at_end) {
      return { done: true }
    }

    // save advancing pointer
    this._start = new _point(returnedKey, false)
    // return value
    if( keyValue[1] === ''  || keyValue[1] === undefined) keyValue[1] = null

    // NOTE: this is added for backward compatibility. To be removed in the next version.  
    if(keyValue[0] == '\x00') keyValue[0] = ''
    if(keyValue[1] == '\x00') keyValue[1] = ''



    const returnedValue = { value: undefined, done: this._at_end }

    switch (this._view) {
      case IRISIterator.VIEW.SUBSCRIPTS:
        returnedValue.value = keyValue[0]
        break
      case IRISIterator.VIEW.VALUES:
        returnedValue.value = keyValue[1]
        break
      case IRISIterator.VIEW.ITEMS:
        returnedValue.value = keyValue
        break
      case IRISIterator.VIEW.NODES:
        // TODO: Ask Mo if python implementation correct: it has keyValue[1]
        returnedValue.value = this._iris.node(this._global_name, ...this._subscripts, keyValue[0])
        break
      case IRISIterator.VIEW.NODEITEMS:
        returnedValue.value = [keyValue[0], this._iris.node(this._global_name, ...this._subscripts, keyValue[0])]
        break
      default:
        throw new Error('Unrecognized view type')
    }

    return returnedValue

  }

  reversed () {
    this._reversed = !this._reversed
    if (this._at_end == true) this._at_end = false
    return this
  }

  keys () {
    this._view = IRISIterator.VIEW.SUBSCRIPTS
    return this
  }

  subscripts () {
    return this.keys()
  }

  values () {
    this._view = IRISIterator.VIEW.VALUES
    return this
  }

  entries () {
    this._view = IRISIterator.VIEW.ITEMS
    return this
  }

  nodes () {
    this._view = IRISIterator.VIEW.NODES
    return this
  }
  
  nodeEntries () {
    this._view = IRISIterator.VIEW.NODEITEMS
    return this
  }

  startFrom (subscript) {
    if (typeof subscript == 'object' 
    && !((subscript instanceof ArrayBuffer) || (subscript instanceof Buffer))) {
      throw new TypeError('IRIS Native: Object type unsupported')
    }

    if (typeof subscript == 'undefined') {
      throw new TypeError('IRIS Native: Unsupported N-API value type')
    }
    
    this._start = new _point(subscript, false)
    this._at_end = false
    return this
  }

  /**
   * Returns the next node from the IRIS server. If the IRIS server protocol
   * is 63 or later, then next node with stop is supported.
   * @function _nextNode
   * @returns the next key-value pair
   * @memberof module:"intersystems-iris".Iterator
   */
  _nextNode () {
    if (this._stop._key === undefined) {
      return this._iris._nextNode(this._reversed, this._global_name, ...this._subscripts, this._start._key)
    }
    const SUPPORT_STOP_ON = this._iris._connection.protocolVersion >= 63
    if (SUPPORT_STOP_ON) {
      const keyValue = this._iris._nextNodeWithStop(this._reversed, this._stop._key, this._global_name, ...this._subscripts, this._start._key)
      if (!this._stop._inclusive && (keyValue[0] === this._stop._key)) {
        this._at_end = true
      }
      return keyValue
    } else {
      const keyValue = this._iris._nextNode(this._reversed, this._global_name, ...this._subscripts, this._start._key)
      if (this._hasPassedStop(keyValue[0])) {
        this._at_end = true
      }
      return keyValue
    }
  }

  /**
   * Returns whether the provided subscript value is beyond the stop value
   * @function _hasPassedStop
   * @param {*} currentValue the current subscript value
   * @returns true if the current subscript is beyond the stop value; false otherwise
   * @memberof module:"intersystems-iris".Iterator
   */
  _hasPassedStop (currentValue) {
    if (this._stop._key === undefined) {
      return false
    }
    const val = _point._sortOrderByKey(this._iris, this._global_name, this._stop._key, currentValue)
    return ( (!this._reversed &&  this._stop._inclusive && (val > 0)) 
          || (!this._reversed && !this._stop._inclusive && (val >= 0))
          || ( this._reversed &&  this._stop._inclusive && (val < 0)) 
          || ( this._reversed && !this._stop._inclusive && (val <= 0)))
  }

  /**
   * This is an internal method intended to be used for debugging purposes only.
   * Returns a formatted string that describes the state of slicing in the IRISGlobalNode object.
   * IRISGlobalNode object can be sliced to limit the subscript traversing range.
   * node.slice(start,end). This results in a new IRISGlobalNode object with the subsript 
   * range limited to from start (inclusive) to stop (exclusive). The only way to traverse the node
   * using a slice is the forward direction. The formatted string uses the standard mathematical 
   * notation of bracketing. Square brackets, [], are used to denote closed intervals with 
   * inclusive endpoints. Parentheses, (), are used to denote open intervals with exclusive 
   * endpoints. For example, "[ 3 >>> 7 )" means from 3 to 7, forward direction, inclusive of 3 
   * but exclusive of 7. This is what you will get with a simple slicing of node[3:7]
   * @function _sliceState
   * @returns A string representation of the slice state
   * @memberof module:"intersystems-iris".Iterator
   */ 
  _sliceState () {
    let leftBracket = ''
    let leftKey = ''
    let arrows = ''
    let rightKey = ''
    let rightBracket = ''

    leftBracket = this._start._inclusive ? '[ ' : '( '
    leftKey = (this._start._key === undefined) ? 'undefined' : ('\'' + this._stop._key.replace('\'', '\\\'') + '\'')
    arrows = ' >>> '
    rightKey = (this._stop._key === undefined) ? 'undefined' : ('\'' + this._start._key.replace('\'', "\\'") + '\'')
    rightBracket = this._stop._inclusive ? ' ]' : ' )'
    
    return leftBracket + leftKey + arrows + rightKey + rightBracket
  }
}

/**
 * Internal view used during iteration. Allows us to pick what value
 * we will return to the user based on whether she chose to receive only
 * entries (subscript-value pairs), values, keys/subscripts, nodes or node-subscript pairs.
 * @typedef VIEW
 * @property {number} SUBSCRIPTS 1
 * @property {number} VALUES 2
 * @property {number} ITEMS 3
 * @property {number} NODES 4
 * @property {number} NODEITEMS 5
 * @memberof module:"intersystems-iris".Iterator
 */
IRISIterator.VIEW = {
  SUBSCRIPTS: 1,
  VALUES: 2,
  ITEMS: 3, 
  NODES: 4,
  NODEITEMS: 5
}

module.exports.IRISIterator = IRISIterator
